package co.edu.cinematch.core.model;
public class Asiento implements Identifiable { private String id; private String salaId; private String fila; private int numero; private boolean ocupado; public Asiento(){} public Asiento(String salaId,String fila,int numero){this.salaId=salaId;this.fila=fila;this.numero=numero;} public String getId(){return id;}public void setId(String v){id=v;}public String getSalaId(){return salaId;}public void setSalaId(String v){salaId=v;}public String getFila(){return fila;}public void setFila(String v){fila=v;}public int getNumero(){return numero;}public void setNumero(int v){numero=v;}public boolean isOcupado(){return ocupado;}public void setOcupado(boolean v){ocupado=v;} }
